var AGENT_PORTS = [18789, 18790, 3e3, 8080, 8443, 17670];
function checkPort(host, port, timeout = 1e3) {
  return new Promise((resolve9) => {
    const socket = createConnection({ host, port });
    socket.setTimeout(timeout);
    socket.on("connect", () => {
      socket.destroy();
      resolve9(true);
    });
    socket.on("timeout", () => {
      socket.destroy();
      resolve9(false);
    });
    socket.on("error", () => {
      socket.destroy();
      resolve9(false);
    });
  });
}
